import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int correctPin = 4821;
        int correctOtp = 9024;

        System.out.print("Enter 4-digit Account PIN: ");
        int enteredPin = scanner.nextInt();

        // Tier 1 Check: PIN
        if (enteredPin == correctPin) {
            System.out.println("PIN Verified. Sending 2FA SMS Code...");

            System.out.print("Enter 4-digit OTP: ");
            int enteredOtp = scanner.nextInt();

            // Tier 2 Check: OTP (Nested)
            if (enteredOtp == correctOtp) {
                System.out.println("SUCCESS: Authentication Complete! Access Granted.");
            } else {
                System.out.println("SECURITY ALERT: Invalid OTP. Access Denied.");
            }
        } else {
            System.out.println("ERROR: Incorrect Account PIN. Access Denied.");
        }

        scanner.close();
    }
}

