import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int pin = scanner.nextInt();
        int otp = scanner.nextInt();
        if (pin == 1234) {
            if (otp == 5678) {
                System.out.println("Access Granted");
            } else {
                System.out.println("Wrong OTP");
            }
        } else {
            System.out.println("Wrong PIN");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int age = scanner.nextInt();
        double weight = scanner.nextDouble();
        if (age >= 18) {
            if (weight >= 50.0) {
                System.out.println("Eligible to donate blood");
            } else {
                System.out.println("Underweight for donation");
            }
        } else {
            System.out.println("Must be at least 18");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int age = scanner.nextInt();
        boolean test = scanner.nextBoolean();
        if (age >= 18) {
            if (test) {
                System.out.println("Issue Driving License");
            } else {
                System.out.println("Must pass written test first");
            }
        } else {
            System.out.println("Underage for license");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        boolean isMember = scanner.nextBoolean();
        boolean isFormal = scanner.nextBoolean();
        if (isMember) {
            if (isFormal) {
                System.out.println("Welcome to the VIP Lounge");
            } else {
                System.out.println("Entry Denied: Formal attire required");
            }
        } else {
            System.out.println("Entry Denied: Membership required");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double bal = scanner.nextDouble();
        double amt = scanner.nextDouble();
        if (amt <= 10000.0) {
            if (amt <= bal) {
                System.out.println("Dispensing Cash");
            } else {
                System.out.println("Insufficient Balance");
            }
        } else {
            System.out.println("Exceeds Daily Limit of 10000");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int credits = scanner.nextInt();
        double gpa = scanner.nextDouble();
        if (credits >= 120) {
            if (gpa >= 3.8) {
                System.out.println("Graduating with High Honors");
            } else if (gpa >= 3.5) {
                System.out.println("Graduating with Honors");
            } else {
                System.out.println("Graduating");
            }
        } else {
            System.out.println("Incomplete Credits: " + (120 - credits) + " needed");
        }
        scanner.close();
    }
}

